mapper.select:
select group_concat(m.id) from safety_field_manage m where m.field_code in

  #{item}

 and m.field_type = 'factory' group by m.field_type

select group_concat(m.field_code) from safety_field_manage m where m.id in

  #{item}

and m.field_type = 'factory' group by m.field_type

select d.empower_no from safety_empower_device d
                    where d.empower_type = #{empowerType}
                      and d.region_name = #{regionName}

                        and d.factory_id in

                          #{ll}


                      and d.delete_falg = 0

select * from ( select p.emp_no,d.empower_no as power_no from safety_outsider_promise p right join safety_empower_device d on FIND_IN_SET(d.factory_id,p.factory) where p.emp_no in
#{ll}
and d.empower_type = '外协' and d.region_name = '大门人脸' ) aa where aa.power_no is not null

select
    flow_id
from safety_outsider_promise_change
where status = '30'

  and publish_time >= #{beginTime}
  and publish_time < #{endTime}

select  pc.creator_name       as submitter,
        pc.creator            as submitterId,
        pc.creator_dept       as department,
        pd.emp_name           as cooperativePerson,
        pd.emp_no             as cooperativePersonId,
        pd.org                as cooperativeOrganization,
        p.factory             as authorizedFacility,
        pd.factory            as changedFacility,
        p.service_end_date    as beforeEndDate,
        pd.service_end_date   as afterEndDate,
        pc.section_chief_name as departmentHead,
        pc.status             as processStatus,
        pc.create_time        as submissionTime,

            CONCAT(#{bpmUrlPre},'&formInstanceId=',pc.id,'&processId=',pc.flow_id) as bpmUrl

from safety_outsider_promise_change pc
left join safety_outsider_promise_change_detail pd on pc.flow_id = pd.flow_id
left join safety_outsider_promise_change_history p on p.flow_id = pd.flow_id and p.emp_no = pd.emp_no


  and pc.flow_id = #{flowId}


    AND pc.creator_name = #{submitter}


    AND pc.creator = #{submitterId}


    AND pc.creator_dept = #{department}


    AND pd.emp_name = #{cooperativePerson}


    AND pd.emp_no = #{cooperativePersonId}


    AND pd.org = #{cooperativeOrganization}


    and FIND_IN_SET (#{authorizedFacility},p.factory)


    and FIND_IN_SET (#{changedFacility},pd.factory)


    AND pc.section_chief_name = #{departmentHead}


    AND pc.status = #{processStatus}


    AND pc.create_time >= #{submissionStartTime}



    AND pc.create_time <= #{submissionEndTime}



order by pc.create_time desc


    limit ${offset}, ${limit}


    limit ${limit}

select  count(1)
from safety_outsider_promise_change pc
left join safety_outsider_promise_change_detail pd on pc.flow_id = pd.flow_id
left join safety_outsider_promise p on p.emp_no = pd.emp_no


    AND pc.creator_name = #{submitter}


    AND pc.creator = #{submitterId}


    AND pc.creator_dept = #{department}


    AND pd.emp_name = #{cooperativePerson}


    AND pd.emp_no = #{cooperativePersonId}


    AND pd.org = #{cooperativeOrganization}


    and FIND_IN_SET (#{authorizedFacility},p.factory)


    and FIND_IN_SET (#{changedFacility},pd.factory)


    AND pc.section_chief_name = #{departmentHead}


    AND pc.status = #{processStatus}


    AND pc.create_time >= #{submissionStartTime}



    AND pc.create_time <= #{submissionEndTime}

SELECT a.emp_no AS empNo, a.emp_name AS empname, a.factory AS factoryId, a.service_end_date AS powerEndTime, a.creator_name as creatorName, a.creator_no as creatorNo, a.emp_org as empOrg, a.remark as remark, a.status as status, b.phone_no AS phoneNo, b.org_name_path as orgNamePath, b.org_code_path as orgCodePath, 'WX' AS userType FROM safety_outsider_promise a LEFT JOIN safety_employee_message b ON a.emp_no = b.emp_no WHERE a.card_status = '0' and a.status = '1' and a.update_time > DATE_SUB(now(), INTERVAL 3 DAY)
and a.emp_no in
